double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

int cmp(const void *a, const void *b) {
    Point *p = (Point*)a;
    Point *q = (Point*)b;
    if (p->x != q->x) return (p->x < q->x) ? -1 : 1;
    if (p->y != q->y) return (p->y < q->y) ? -1 : 1;
    return 0;
}

int main() {
    int n;
    scanf("%d", &n);

    Point *pts = (Point*)malloc(n * sizeof(Point));
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &pts[i].x, &pts[i].y);
    }

    if (n == 1) {
        printf("%.6f\n", 0.0);
        free(pts);
        return 0;
    }
    if (n == 2) {
        printf("%.6f\n", sqrt(dist2(pts[0], pts[1])));
        free(pts);
        return 0;
    }

    // Compute convex hull using Andrew's monotone chain
    qsort(pts, n, sizeof(Point), cmp);

    Point *hull = (Point*)malloc(2 * n * sizeof(Point));
    int k = 0;

    // Lower hull
    for (int i = 0; i < n; i++) {
        while (k >= 2 && cross(hull[k-2], hull[k-1], pts[i]) <= 0)
            k--;
        hull[k++] = pts[i];
    }

    // Upper hull
    for (int i = n-2, t = k+1; i >= 0; i--) {
        while (k >= t && cross(hull[k-2], hull[k-1], pts[i]) <= 0)
            k--;
        hull[k++] = pts[i];
    }
    k--; // Remove last point (same as first)

    if (k == 1) {
        printf("%.6f\n", 0.0);
        free(pts); free(hull);
        return 0;
    }
    if (k == 2) {
        printf("%.6f\n", sqrt(dist2(hull[0], hull[1])));
        free(pts); free(hull);
        return 0;
    }

    // Rotating calipers
    double maxDist = 0;
    int j = 1;
    for (int i = 0; i < k; i++) {
        Point a = hull[i];
        Point b = hull[(i+1) % k];
        // Advance j while the next position gives larger distance
        while (1) {
            Point c = hull[j];
            Point d = hull[(j+1) % k];
            // Cross product to determine if we should advance
            double cx = (b.x - a.x);
            double cy = (b.y - a.y);
            double dx2 = d.x - c.x;
            double dy2 = d.y - c.y;
            // Check if rotating caliper: cross product of edge with (d-c)
            if (cx * dy2 - cy * dx2 > 0)
                j = (j + 1) % k;
            else
                break;
        }
        double d1 = dist2(hull[i], hull[j]);
        double d2 = dist2(hull[(i+1)%k], hull[j]);
        double d3 = dist2(hull[i], hull[(j+1)%k]);
        if (d1 > maxDist) maxDist = d1;
        if (d2 > maxDist) maxDist = d2;
        if (d3 > maxDist) maxDist = d3;
    }

    printf("%.6f\n", sqrt(maxDist));

    free(pts);
    free(hull);
    return 0;
}

