import java.util.*;

public class ConvexPolygonDiameter {
    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static long dist2(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    static List<Point> convexHull(Point[] pts) {
        int n = pts.length;
        Arrays.sort(pts, (p, q) -> {
            if (p.x != q.x) return Long.compare(p.x, q.x);
            return Long.compare(p.y, q.y);
        });

        List<Point> hull = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            while (hull.size() >= 2 && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), pts[i]) <= 0)
                hull.remove(hull.size()-1);
            hull.add(pts[i]);
        }
        int lowerLen = hull.size();
        for (int i = n-2; i >= 0; i--) {
            while (hull.size() > lowerLen && cross(hull.get(hull.size()-2), hull.get(hull.size()-1), pts[i]) <= 0)
                hull.remove(hull.size()-1);
            hull.add(pts[i]);
        }
        hull.remove(hull.size()-1);
        return hull;
    }

    static long diameter(List<Point> poly) {
        int n = poly.size();
        if (n == 2) return dist2(poly.get(0), poly.get(1));

        int k = 1;
        long maxDist = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            while (true) {
                maxDist = Math.max(maxDist, dist2(poly.get(i), poly.get(k)));
                maxDist = Math.max(maxDist, dist2(poly.get(j), poly.get(k)));
                // rotate k while cross product increases
                int nextK = (k + 1) % n;
                if (cross(poly.get(i), poly.get(j), poly.get(nextK)) > cross(poly.get(i), poly.get(j), poly.get(k)))
                    k = nextK;
                else
                    break;
            }
        }
        return maxDist;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        Point[] pts = new Point[n];
        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            long x = Long.parseLong(st.nextToken());
            long y = Long.parseLong(st.nextToken());
            pts[i] = new Point(x, y);
        }
        List<Point> hull = convexHull(pts);
        long ans = diameter(hull);
        System.out.println(ans);
    }
}

