public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        double[] x = new double[n];
        double[] y = new double[n];

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            x[i] = Double.parseDouble(st.nextToken());
            y[i] = Double.parseDouble(st.nextToken());
        }

        if (n == 1) {
            System.out.printf("%.6f%n", 0.0);
            return;
        }
        if (n == 2) {
            double dx = x[0] - x[1];
            double dy = y[0] - y[1];
            System.out.printf("%.6f%n", Math.sqrt(dx*dx + dy*dy));
            return;
        }

        // Ensure convex hull is in counter-clockwise order
        // First, find the bottom-most point
        int start = 0;
        for (int i = 1; i < n; i++) {
            if (y[i] < y[start] || (y[i] == y[start] && x[i] < x[start])) {
                start = i;
            }
        }
        // Rotate so that start is first
        double[] nx = new double[n];
        double[] ny = new double[n];
        for (int i = 0; i < n; i++) {
            nx[i] = x[(i + start) % n];
            ny[i] = y[(i + start) % n];
        }
        x = nx; y = ny;

        // Check orientation - make sure it's CCW
        double cross = (x[1]-x[0])*(y[2]-y[0]) - (y[1]-y[0])*(x[2]-x[0]);
        if (cross < 0) {
            // Reverse to make CCW
            for (int i = 0, j = n-1; i < j; i++, j--) {
                double tmp = x[i]; x[i] = x[j]; x[j] = tmp;
                tmp = y[i]; y[i] = y[j]; y[j] = tmp;
            }
        }

        // Rotating calipers
        double maxDist = 0;
        int j = 1;
        for (int i = 0; i < n; i++) {
            int ni = (i + 1) % n;
            // Advance j while the next j gives larger cross product (area of parallelogram)
            while (true) {
                int nj = (j + 1) % n;
                // Cross product of edge i->ni with vector i->nj vs i->j
                double ex = x[ni] - x[i];
                double ey = y[ni] - y[i];
                double c1 = ex * (y[nj] - y[i]) - ey * (x[nj] - x[i]);
                double c2 = ex * (y[j] - y[i]) - ey * (x[j] - x[i]);
                if (c1 > c2) {
                    j = nj;
                } else {
                    break;
                }
            }
            // Check distances
            double d1 = dist(x[i], y[i], x[j], y[j]);
            double d2 = dist(x[ni], y[ni], x[j], y[j]);
            maxDist = Math.max(maxDist, Math.max(d1, d2));
        }

        System.out.printf("%.6f%n", maxDist);
    }

    static double dist(double x1, double y1, double x2, double y2) {
        double dx = x1 - x2;
        double dy = y1 - y2;
        return Math.sqrt(dx*dx + dy*dy);
    }
}

