public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long cross(Point a, Point b, Point c) {
        // (b-a) x (c-a)
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static long dist2(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n;
        try {
            n = fs.nextInt();
        } catch (Exception e) {
            return;
        }

        Point[] p = new Point[n];
        for (int i = 0; i < n; i++) {
            long x = fs.nextLong();
            long y = fs.nextLong();
            p[i] = new Point(x, y);
        }

        if (n == 1) {
            System.out.println("0.0000000000");
            return;
        }
        if (n == 2) {
            System.out.printf(Locale.US, "%.10f%n", Math.sqrt(dist2(p[0], p[1])));
            return;
        }

        // Rotating calipers for convex polygon diameter.
        // Assumes vertices are given in order (clockwise or counterclockwise).
        int j = 1;
        while (Math.abs(cross(p[n - 1], p[0], p[(j + 1) % n])) > Math.abs(cross(p[n - 1], p[0], p[j]))) {
            j++;
        }

        long best = 0;
        int startJ = j;

        for (int i = 0; i < n; i++) {
            int ni = (i + 1) % n;

            best = Math.max(best, dist2(p[i], p[j]));
            best = Math.max(best, dist2(p[ni], p[j]));

            while (Math.abs(cross(p[i], p[ni], p[(j + 1) % n])) > Math.abs(cross(p[i], p[ni], p[j]))) {
                j = (j + 1) % n;
                best = Math.max(best, dist2(p[i], p[j]));
                best = Math.max(best, dist2(p[ni], p[j]));
            }

            if (j == startJ && i > 0) {
                // full cycle completed
                // not strictly necessary, but avoids redundant work
            }
        }

        System.out.printf(Locale.US, "%.10f%n", Math.sqrt(best));
    }
