def squared_distance(p1, p2):
    return (p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2

def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def rotating_calipers(poly):
    n = len(poly)
    if n == 2:
        return squared_distance(poly[0], poly[1])

    # Find the point with max x (and min x for start)
    left = 0
    right = 0
    for i in range(n):
        if poly[i][0] < poly[left][0]:
            left = i
        if poly[i][0] > poly[right][0]:
            right = i

    max_dist = squared_distance(poly[left], poly[right])

    # Rotating calipers
    for _ in range(n):
        next_left = (left + 1) % n
        next_right = (right + 1) % n
        # Compare cross product to decide which to advance
        if cross(poly[left], poly[next_left], poly[right]) < cross(poly[left], poly[next_left], poly[next_right]):
            right = next_right
        else:
            left = next_left
        max_dist = max(max_dist, squared_distance(poly[left], poly[right]))

    return max_dist

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    points = [(int(data[1 + 2*i]), int(data[2 + 2*i])) for i in range(n)]

    # Already convex and given in order (CCW or CW)
    # We just apply rotating calipers
    result = rotating_calipers(points)
    print(result)

if __name__ == "__main__":
    main()

import sys
from math import sqrt

def cross(O, A, B):
    return (A[0] - O[0]) * (B[1] - O[1]) - (A[1] - O[1]) * (B[0] - O[0])

def dist2(A, B):
    return (A[0]-B[0])**2 + (A[1]-B[1])**2

def convex_hull(points):
    points = sorted(set(points))
    n = len(points)
    if n <= 1:
        return points
    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)
    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)
    return lower[:-1] + upper[:-1]

def rotating_calipers_diameter(hull):
    n = len(hull)
    if n == 1:
        return 0.0
    if n == 2:
        return sqrt(dist2(hull[0], hull[1]))

    max_dist2 = 0
    j = 1
    for i in range(n):
        # Advance j while the next position gives larger distance
        while True:
            next_j = (j + 1) % n
            # Check if moving j forward increases distance from hull[i]
            # Use cross product to determine if we should advance
            ax = hull[(i+1)%n][0] - hull[i][0]
            ay = hull[(i+1)%n][1] - hull[i][1]
            bx = hull[next_j][0] - hull[j][0]
            by = hull[next_j][1] - hull[j][1]
            if ax * by - ay * bx > 0:
                j = next_j
            else:
                break
        max_dist2 = max(max_dist2, dist2(hull[i], hull[j]))
        # Also check i with next_j to avoid missing cases
        max_dist2 = max(max_dist2, dist2(hull[i], hull[(j+1)%n]))
    return sqrt(max_dist2)

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    results = []

    while idx < len(input_data):
        n = int(input_data[idx]); idx += 1
        if n == 0:
            break
        points = []
        for _ in range(n):
            x = float(input_data[idx]); idx += 1
            y = float(input_data[idx]); idx += 1
            points.append((x, y))

        if n == 1:
            results.append("0.000")
            continue

        # Convert to tuples for hull (need to handle float coordinates)
        hull = convex_hull(points)

        diameter = rotating_calipers_diameter(hull)
        results.append("{:.6f}".format(diameter))

    for r in results:
        print(r)

solve()

import sys

def cross(ax, ay, bx, by):
    return ax * by - ay * bx

def area2(a, b, c):
    return cross(b[0] - a[0], b[1] - a[1], c[0] - a[0], c[1] - a[1])

def dist2(p, q):
    dx = p[0] - q[0]
    dy = p[1] - q[1]
    return dx * dx + dy * dy

def polygon_diameter(points):
    n = len(points)
    if n == 1:
        return 0
    if n == 2:
        return dist2(points[0], points[1])

    # Rotating calipers for convex polygon in CCW order
    j = 1
    best = 0

    for i in range(n):
        ni = (i + 1) % n
        # Move j while area increases
        while True:
            nj = (j + 1) % n
            cur = abs(area2(points[i], points[ni], points[j]))
            nxt = abs(area2(points[i], points[ni], points[nj]))
            if nxt > cur:
                j = nj
            else:
                break

        best = max(best, dist2(points[i], points[j]), dist2(points[ni], points[j]))

    return best

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    pts = []
    idx = 1
    for _ in range(n):
        x = int(data[idx]); y = int(data[idx + 1])
        idx += 2
        pts.append((x, y))

    print(polygon_diameter(pts))

